begin; do $$ declare actor uuid:=gen_random_uuid(); inv text:=gen_random_uuid()::text; n bigint; begin insert into auth.users(id) values(actor); insert into public.profiles(id,email,nombre,rol,activo) values(actor,actor::text||'@example.invalid','Prueba borrador','admin',true); perform set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true); set local role authenticated; insert into public.facturas(id,area,linea_negocio,tipo,numero,cliente,concepto,fecha,estado,base_imponible,porcentaje_iva,importe_iva,total,datos_cliente_borrador) values(inv,'montada','montada_sound','emitida','','Prueba','Sonido',current_date,'borrador',100,21,21,121,'{"nombre":"Prueba","nifCif":"TEST","direccion":"Prueba"}'); update public.facturas set concepto='Sonido y técnico',base_imponible=200,importe_iva=42,total=242,datos_cliente_borrador='{"nombre":"Prueba editada","nifCif":"TEST","direccion":"Prueba"}' where id=inv; if (select datos_cliente_borrador->>'nombre' from public.facturas where id=inv)<>'Prueba editada' then raise exception 'Edit failed'; end if; delete from public.facturas where id=inv; if exists(select 1 from public.facturas where id=inv) then raise exception 'Delete failed'; end if; insert into public.facturas(id,area,linea_negocio,tipo,numero,cliente,concepto,fecha,estado) values(inv,'montada','montada_sound','emitida','','Prueba','Sonido',current_date,'borrador'); perform public.emitir_factura_independiente(inv,'montada','emitida','Prueba',E'Sonido\n[2 x 100.00 EUR; descuento/u 0.00 EUR; total 200.00 EUR]',200,21,42,242,current_date::text,null,100,null,'{"nombre":"Prueba","nifCif":"TEST","direccion":"Prueba"}'); begin delete from public.facturas where id=inv; raise exception 'Deletion allowed'; exception when insufficient_privilege then null; end; begin update public.facturas set datos_cliente_borrador='{}' where id=inv; raise exception 'Issued mutation allowed'; exception when insufficient_privilege then null; end; end $$; rollback;
